let FORALL_UNPAIR_FUN_THM = prove
 (`!P:(A->B)->(A->C)->bool. (!f g. P f g) <=> (!h. P (FST o h) (SND o h))`,
  REWRITE_TAC[FORALL_PAIR_FUN_THM; o_DEF; ETA_AX]);;

let EXISTS_UNPAIR_FUN_THM = prove
 (`!P:(A->B)->(A->C)->bool. (?f g. P f g) <=> (?h. P (FST o h) (SND o h))`,
